import sys

# Minimal YAML parser for a flat and one-level-nested subset
# Assumes keys and simple values, or single-level dicts only
# Example:
# key1: value1
# key2:
#   subkey1: subvalue1
#   subkey2: subvalue2

def parse_yaml(content):
    result = {}
    current_key = None
    indent_level = None
    for line in content.splitlines():
        line = line.rstrip()
        if not line or line.lstrip().startswith('#'):
            continue
        if line.startswith(' '):
            # Nested key
            if current_key is not None:
                parts = line.strip().split(':', 1)
                if len(parts) == 2:
                    k, v = parts
                    v = v.strip() or None
                    if v is None:
                        v = ''
                    result[current_key][k.strip()] = v
            else:
                raise ValueError('Nested key without a parent key')
        else:
            # New key
            parts = line.split(':', 1)
            if len(parts) == 2:
                k, v = parts
                k = k.strip()
                v = v.strip() or None
                if v is None:
                    result[k] = {}
                    current_key = k
                else:
                    result[k] = v
                    current_key = None
    return result


def deep_merge(dict1, dict2):
    merged = dict1.copy()
    for k, v in dict2.items():
        if k in merged:
            if isinstance(merged[k], dict) and isinstance(v, dict):
                merged[k] = deep_merge(merged[k], v)
            else:
                merged[k] = v
        else:
            merged[k] = v
    return merged


def to_yaml(d, indent=0):
    lines = []
    for k, v in d.items():
        if isinstance(v, dict):
            lines.append(' ' * indent + f'{k}:')
            lines.extend(to_yaml(v, indent + 2))
        else:
            lines.append(' ' * indent + f'{k}: {v}')
    return lines


def main():
    if len(sys.argv) != 3:
        print('Usage: python yamlmerge.py file1.yaml file2.yaml')
        sys.exit(1)

    with open(sys.argv[1], 'r') as f1:
        yaml1 = parse_yaml(f1.read())
    with open(sys.argv[2], 'r') as f2:
        yaml2 = parse_yaml(f2.read())

    merged = deep_merge(yaml1, yaml2)
    print('\n'.join(to_yaml(merged)))


if __name__ == '__main__':
    main()
